<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Payment; use Illuminate\Http\Request;
class PaymentController extends Controller { public function index(){return Payment::with('member')->latest('payment_date')->paginate(50);} public function store(Request $r){$d=$r->validate(['member_id'=>'required|exists:members,id','payment_date'=>'required|date','maintenance_month'=>'required','amount'=>'required|numeric','payment_mode'=>'required','reference'=>'nullable','remarks'=>'nullable']); $d['receipt_no']='R-'.str_pad((string)(Payment::max('id')+1),5,'0',STR_PAD_LEFT); return Payment::create($d);} public function show(Payment $payment){return $payment->load('member');} public function update(Request $r,Payment $payment){$payment->update($r->all()); return $payment;} public function destroy(Payment $payment){$payment->delete(); return response()->noContent();} }
